                m2, b2 = hull[-1]

                if (intercept - b2) * (m1 - m2) >= (b2 - b1) * (m2 - slope):
                    hull.pop()
                else:
                    break

            hull.append((slope, intercept))

        start = 0

        for j in range(1, len(mana)):
            left, right = 0, len(hull) - 1

            while left < right:
                mid = (left + right) // 2

                m1, b1 = hull[mid]
                m2, b2 = hull[mid + 1]

